/**
 * The live dashboards (examples/dashboards, generated by scripts/dashboards/build.mjs): each PBIP opens without
 * diagnostics, refreshes offline from its embedded data, and every visual of every page resolves its fields and returns
 * data under the saved filters (the year slicer opens on 2026; Regolith's space mining data is 2069–2070 and opens on 2070).
 *
 * LUMEN_DASHBOARDS_WBI=/abs/dir also saves each refreshed dashboard there as a `.wbi` bundle (PBIP + data), the file
 * to open in Lumen and publish.
 */
import { readdirSync } from 'node:fs'
import { join } from 'node:path'
import { describe, expect, it } from 'vitest'
import { openProject, saveProject } from '@core/io/open'
import { nodeFs } from '@core/io/nodefs'
import { refreshProject } from '@core/data/refresh'
import type { RefreshHost } from '@core/data/fetcher'
import { createEngine } from '@core/engine/engine'
import { probeReport } from '@renderer/app/sweep/probe'

const ROOT = __dirname
const WBI_OUT = process.env.LUMEN_DASHBOARDS_WBI ?? ''
const DASHBOARDS = readdirSync(ROOT, { withFileTypes: true }).filter((d) => d.isDirectory()).map((d) => d.name).sort()

const offline: RefreshHost = {
  fs: nodeFs as unknown as RefreshHost['fs'],
  now: () => new Date(Date.UTC(2026, 10, 23, 15, 0)),
  localOffsetMinutes: 0,
  connectors: {} as RefreshHost['connectors']
}

// the year each dashboard opens on, and its calendar's length in days
const YEAR: Record<string, { year: number; days: number }> = { Regolith: { year: 2070, days: 730 } }
const yearOf = (name: string) => YEAR[name] ?? { year: 2026, days: 669 }

const DATA_FREE = new Set(['textbox', 'image', 'shape', 'actionButton', 'pageNavigator', 'bookmarkNavigator'])
// blank in 2026 by design: trees planted this year get their first-year survival check next season
const BLANK_IN_2026 = new Set(['kpi_tree_survival_pct'])

async function load(name: string) {
  const doc = await openProject(join(ROOT, name, `${name}.pbip`), nodeFs)
  const r = await refreshProject(doc, offline)
  return { doc, r }
}

describe('live dashboards', () => {
  it('Orbital, Contour, Aurora and Regolith', () => {
    expect(DASHBOARDS).toEqual(['Aurora', 'Contour', 'Orbital', 'Regolith'])
  })

  for (const name of DASHBOARDS) {
    describe(name, () => {
      it('opens and refreshes offline: every table loads, measures in the two measure tables', async () => {
        const { doc, r } = await load(name)
        expect(doc.diagnostics.filter((d) => d.level === 'error')).toEqual([])
        expect(r.tables.filter((t) => !t.ok)).toEqual([])
        const cal = doc.data.tables.get('dim_calendar')!
        expect(cal.rowCount).toBe(yearOf(name).days)
        for (const t of doc.model.tables.filter((t) => !t.name.startsWith('_measures_'))) {
          expect(t.measures, t.name).toEqual([])
          expect(doc.data.tables.get(t.name)?.rowCount ?? 0, t.name).toBeGreaterThan(0)
        }
        const engine = createEngine(doc.model, doc.data)
        for (const t of doc.model.tables.filter((t) => t.name.startsWith('_measures_')))
          for (const ms of t.measures.filter((m) => !BLANK_IN_2026.has(m.name))) {
            const v = engine.evaluateScalar(`CALCULATE([${ms.name}], dim_calendar[year] = ${yearOf(name).year})`)
            expect(v.value, `[${ms.name}]`).not.toBeNull()
          }
        if (WBI_OUT) await saveProject(doc, join(WBI_OUT, `${name}.wbi`), nodeFs, { format: 'wbi' })
      })

      it('every visual returns data under the saved filters', async () => {
        const { doc } = await load(name)
        const engine = createEngine(doc.model, doc.data)
        const probes = probeReport(engine, doc.report!)
        const bad = probes
          .filter((p) => !DATA_FREE.has(p.visualType))
          .filter((p) => p.error || p.warnings?.length || !(p.rows ?? 0) || p.totals?.some((t) => t.value === null || t.value === undefined))
          .map((p) => `${p.pageDisplayName} / ${p.visualType} ${p.title ?? p.visual}: ${p.error ?? p.warnings?.join('; ') ?? `rows ${p.rows}, totals ${JSON.stringify(p.totals?.map((t) => t.value))}`}`)
        expect(bad).toEqual([])
      })
    })
  }
})
